import json, subprocess, sys, time, random

def big_case(rng, versions=2, runs=64, cache=12, nbursts=4, naddr=64):
    initial=[["::/0",0]]
    for i in range(runs-1):
        initial.append(["%032x/128"%(i+1), i+1])
    transactions=[]
    for v in range(versions-1):
        tx=[]
        for i in range(runs-1):
            if rng.random()<0.5:
                tx.append(['erase', "%032x/128"%(i+1)])
            else:
                tx.append(['set', "%032x/128"%(i+1), rng.randint(0,100)])
        transactions.append(tx)
    bursts=[]
    for b in range(nbursts):
        version=rng.randrange(versions)
        addrs=['%032x'%rng.getrandbits(128) for _ in range(naddr)]
        bursts.append({'version':version,'repeat':rng.randint(1,1000),'addresses':addrs})
    return {'initial':initial,'transactions':transactions,'bursts':bursts,'cache_pages':cache,
            'costs':{'hit':1,'miss':17,'decode':[0,1,2]}}

rng=random.Random(5)
for label, cases in [
    ("2 versions x 64 runs", [big_case(rng, versions=2, runs=64)]),
    ("8 versions x 16 runs", [big_case(rng, versions=8, runs=16)]),
    ("4 cases x 2 versions x 16 runs", [big_case(rng, versions=2, runs=16) for _ in range(4)]),
    ("many routes", None),
]:
    if cases is None:
        # 30000 routes in the initial table, few runs
        case={'initial':[['::/0',0]]+[["%032x/64"%(i*2**64), i] for i in range(1,2000)],
              'transactions':[[['erase',"%032x/64"%(2**64)],['set',"%032x/64"%(3*2**64),77]]],
              'bursts':[{'version':0,'repeat':3,'addresses':['%032x'%(i*2**64) for i in range(64)]}],
              'cache_pages':12,'costs':{'hit':1,'miss':17,'decode':[0,1,2]}}
        cases=[case]
    request={'cases':cases}
    payload=json.dumps(request).encode()
    t=time.time()
    p=subprocess.run(['python3','-B','/workspace/submission/main.py'],input=payload,
                     stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    dt=time.time()-t
    if p.returncode:
        print(label,'FAILED',p.stderr.decode()[:800]); continue
    out=json.loads(p.stdout.decode())
    if 'error' in out:
        print(label,'-> invalid (run bounds)', dt)
    else:
        print(label,'->', out['cases'][0]['objective'], '%.2fs'%dt, 'outbytes',len(p.stdout))
EOF
cd /workspace && python3 tmp/stress.py
